// ============================================================
//  ЧТО НАЖАЛИ
// ============================================================
//
// Telegram присылает callback_data из кнопки — строку вида «смета:0348…».
// Больше 64 байт туда не помещается, поэтому там только номер закупки.
// Адрес карточки приложение найдёт у себя: оно сохранило его в момент,
// когда нашло этот тендер. По номеру портал не ищет — проверено 03.10.2026.

// ТОЛЬКО НАЖАТИЕ КНОПКИ. Найдено 16.10.2026: при запуске воркфлоу из
// редактора n8n (или на пробных данных) сюда приходит не нажатие, номер
// чата пустой, и следующий блок падал с «chat_id пуст». Не нажатие — не
// наше событие: возвращаем пустой список, и воркфлоу тихо останавливается.
const u = $json || {};

// ПОДКЛЮЧЕНИЕ TELEGRAM С САЙТА (21.10.2026). Клиент получает в кабинете
// одноразовый код и отправляет боту «/start КОД». Код проверяет сайт: здесь
// только достаём его и номер чата. Любое другое сообщение - не наше событие.
const м = (u.message && u.data === undefined && !u.callback_query) ? u.message
  : (u.text !== undefined && u.chat && u.data === undefined ? u : null);
if (м) {
  const р = String(м.text || '').trim().match(/^\/start\s+([A-Za-z0-9]{10})$/);
  const чатП = String((м.chat && м.chat.id) || '');
  if (!р || !чатП) return [];
  return { json: { вид: 'привязка', код: р[1].toUpperCase(), chatId: чатП } };
}
const q = u.callback_query || (u.data !== undefined && u.message ? u : null);
if (!q) return [];
const данные = String(q.data || '');
const чат = String((q.message && q.message.chat && q.message.chat.id) || (q.from && q.from.id) || '');
if (!чат || данные.indexOf('смета:') !== 0) return [];

return {
  json: {
    вид: 'смета',
    годится: true,
    номер: данные.slice('смета:'.length).trim(),
    chatId: чат,
    // Кого считаем. Пока один клиент; когда станет больше — здесь будет
    // сопоставление чата с клиентом.
    клиент: 'kargin',
    // Чтобы кнопка перестала «крутиться» в интерфейсе Telegram.
    callbackId: String(q.id || '')
  }
};

// Готовим отправку: файл со сметой или понятное объяснение, почему не вышло.
const r = $json;
const чат = $('Что нажали').first().json.chatId;
const номер = $('Что нажали').first().json.номер;

if (!r || r.ok !== true) {
  return {
    json: {
      естьФайл: false,
      chatId: чат,
      text: '❌ <b>Не удалось посчитать закупку ' + номер + '</b>\n\n'
        + ((r && r.сбой) || 'приложение не ответило')
        + (r && r.подробно ? '\n\n' + r.подробно : '')
    }
  };
}

return {
  json: {
    естьФайл: true,
    chatId: чат,
    // Подпись приходит ГОТОВОЙ и безопасно обрезанной — её собирает
        // приложение (src/notify.js, подписьДляФайла), где это покрыто
        // проверками. Здесь стояло `.slice(0, 1000)`, и 09.10.2026 оно
        // разорвало тег пополам: Telegram отверг сообщение целиком,
        // клиент не получил ни текста, ни файла.
        caption: r.подписьФайла || String(r.подпись || '').slice(0, 900),
    fileName: r.файл.имя
  },
  binary: {
    data: {
      data: r.файл.base64,
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName: r.файл.имя,
      fileExtension: 'xlsx'
    }
  }
};
